import React, { useEffect, useMemo, useState, useRef } from "react";
import { useNavigate } from "react-router-dom";
import {
  createProject,
  createTask,
  getMe,
  getProjects,
  getTasksByProject,
  getUsers,
  updateTask
} from "../services/api";

const emptyProject = { name: "", description: "", memberIds: [] };
const emptyTask = { title: "", description: "", assignedTo: "", dueDate: "" };

const styles = `
  @import url('https://fonts.googleapis.com/css2?family=Syne:wght@400;600;700;800&family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;1,9..40,300&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --bg: #f0f4fa;
    --surface: #ffffff;
    --surface2: #f7f9fc;
    --surface3: #eef2f8;
    --border: rgba(15,23,42,0.08);
    --border-bright: rgba(15,23,42,0.16);
    --text: #0f172a;
    --muted: #64748b;
    --muted2: #94a3b8;
    --accent: #16a34a;
    --accent-light: #dcfce7;
    --accent-dim: rgba(22,163,74,0.12);
    --accent2: #2563eb;
    --accent2-light: #dbeafe;
    --accent2-dim: rgba(37,99,235,0.1);
    --accent3: #dc2626;
    --accent3-dim: rgba(220,38,38,0.1);
    --accent4: #ea580c;
    --accent4-dim: rgba(234,88,12,0.1);
    --purple: #7c3aed;
    --purple-dim: rgba(124,58,237,0.1);
    --danger: #dc2626;
    --radius: 18px;
    --radius-sm: 12px;
    --radius-xs: 8px;
    --shadow-sm: 0 1px 3px rgba(15,23,42,0.06), 0 1px 2px rgba(15,23,42,0.04);
    --shadow: 0 4px 16px rgba(15,23,42,0.08), 0 2px 6px rgba(15,23,42,0.05);
    --shadow-lg: 0 12px 40px rgba(15,23,42,0.12), 0 4px 12px rgba(15,23,42,0.07);
  }

  .dashboard {
    font-family: 'DM Sans', sans-serif;
    background: var(--bg);
    min-height: 100vh;
    color: var(--text);
    position: relative;
    overflow-x: hidden;
  }

  .dashboard::before {
    content: '';
    position: fixed;
    top: -150px; left: -150px;
    width: 500px; height: 500px;
    background: radial-gradient(circle, rgba(37,99,235,0.07) 0%, transparent 70%);
    pointer-events: none; z-index: 0;
  }

  .dashboard::after {
    content: '';
    position: fixed;
    bottom: -150px; right: -80px;
    width: 450px; height: 450px;
    background: radial-gradient(circle, rgba(22,163,74,0.07) 0%, transparent 70%);
    pointer-events: none; z-index: 0;
  }

  .dashboard > * { position: relative; z-index: 1; }

  /* TOPBAR */
  .topbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 40px;
    height: 64px;
    border-bottom: 1px solid var(--border);
    backdrop-filter: blur(16px);
    position: sticky; top: 0; z-index: 200;
    background: rgba(255,255,255,0.88);
    box-shadow: 0 1px 0 var(--border), 0 4px 20px rgba(15,23,42,0.04);
  }

  .topbar-logo {
    display: flex; align-items: center; gap: 10px;
  }

  .logo-mark {
    width: 32px; height: 32px;
    background: linear-gradient(135deg, #0f172a, #1e293b);
    border-radius: 9px;
    display: flex; align-items: center; justify-content: center;
    box-shadow: 0 2px 8px rgba(15,23,42,0.2);
  }

  .topbar h1 {
    font-family: 'Syne', sans-serif;
    font-size: 1.2rem; font-weight: 800;
    letter-spacing: -0.025em; color: var(--text);
  }

  .topbar h1 span { color: var(--accent); }

  .topbar-right { display: flex; align-items: center; gap: 12px; }

  .topbar-badge {
    background: var(--surface2);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 5px 10px;
    font-size: 0.72rem;
    color: var(--muted);
    font-weight: 500;
    letter-spacing: 0.03em;
  }

  .user-pill {
    display: flex; align-items: center; gap: 9px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 100px;
    padding: 5px 14px 5px 5px;
    box-shadow: var(--shadow-sm);
    cursor: default;
    transition: border-color 0.2s;
  }

  .user-pill:hover { border-color: var(--border-bright); }

  .user-avatar {
    width: 30px; height: 30px; border-radius: 50%;
    background: linear-gradient(135deg, var(--accent2), var(--purple));
    display: flex; align-items: center; justify-content: center;
    font-family: 'Syne', sans-serif; font-weight: 800;
    font-size: 0.65rem; color: #fff;
    flex-shrink: 0;
  }

  .user-info { line-height: 1.25; }
  .user-name { font-size: 0.8rem; font-weight: 600; color: var(--text); }
  .user-role {
    font-size: 0.62rem; color: var(--muted);
    text-transform: uppercase; letter-spacing: 0.09em;
  }

  .btn-logout {
    background: transparent;
    border: 1px solid var(--border-bright);
    color: var(--muted);
    padding: 7px 16px;
    border-radius: 100px;
    font-family: 'DM Sans', sans-serif;
    font-size: 0.78rem; font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
  }

  .btn-logout:hover {
    border-color: var(--danger);
    color: var(--danger);
    background: var(--accent3-dim);
  }

  /* MAIN */
  .main-content {
    padding: 32px 40px 80px;
    max-width: 1340px;
    margin: 0 auto;
  }

  .page-header {
    display: flex; justify-content: space-between; align-items: flex-end;
    margin-bottom: 28px;
  }

  .page-title {
    font-family: 'Syne', sans-serif;
    font-size: 1.6rem; font-weight: 800;
    letter-spacing: -0.03em; color: var(--text);
    line-height: 1;
  }

  .page-title span { color: var(--accent2); }
  .page-date { font-size: 0.8rem; color: var(--muted2); }

  /* ERROR */
  .error-bar {
    display: flex; align-items: center; gap: 10px;
    background: var(--accent3-dim);
    border: 1px solid rgba(220,38,38,0.2);
    color: var(--danger);
    padding: 12px 16px; border-radius: var(--radius-sm);
    margin-bottom: 24px; font-size: 0.84rem;
  }

  /* STATS */
  .stats {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px; margin-bottom: 28px;
  }

  .stat-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 22px 24px;
    position: relative; overflow: hidden;
    transition: all 0.25s cubic-bezier(0.4,0,0.2,1);
    cursor: default;
    box-shadow: var(--shadow-sm);
  }

  .stat-card:hover {
    transform: translateY(-3px);
    box-shadow: var(--shadow);
    border-color: var(--border-bright);
  }

  .stat-card-accent {
    position: absolute; top: 0; left: 0; right: 0; height: 3px;
    border-radius: var(--radius) var(--radius) 0 0;
  }

  .stat-card-bg {
    position: absolute; bottom: -16px; right: -16px;
    width: 80px; height: 80px; border-radius: 50%;
    opacity: 0.06; pointer-events: none;
  }

  .stat-card.total .stat-card-accent { background: linear-gradient(90deg, #2563eb, #7c3aed); }
  .stat-card.total .stat-card-bg { background: #2563eb; }
  .stat-card.completed .stat-card-accent { background: linear-gradient(90deg, #16a34a, #059669); }
  .stat-card.completed .stat-card-bg { background: #16a34a; }
  .stat-card.pending .stat-card-accent { background: linear-gradient(90deg, #ea580c, #d97706); }
  .stat-card.pending .stat-card-bg { background: #ea580c; }
  .stat-card.overdue .stat-card-accent { background: linear-gradient(90deg, #dc2626, #e11d48); }
  .stat-card.overdue .stat-card-bg { background: #dc2626; }

  .stat-icon {
    width: 34px; height: 34px; border-radius: 9px;
    display: flex; align-items: center; justify-content: center;
    margin-bottom: 16px;
  }

  .stat-card.total .stat-icon { background: var(--accent2-dim); }
  .stat-card.completed .stat-icon { background: var(--accent-dim); }
  .stat-card.pending .stat-icon { background: var(--accent4-dim); }
  .stat-card.overdue .stat-icon { background: var(--accent3-dim); }

  .stat-label {
    font-size: 0.68rem; font-weight: 600;
    text-transform: uppercase; letter-spacing: 0.1em;
    color: var(--muted); margin-bottom: 6px;
  }

  .stat-value {
    font-family: 'Syne', sans-serif;
    font-size: 2.6rem; font-weight: 800;
    line-height: 1; letter-spacing: -0.04em;
  }

  .stat-card.total .stat-value { color: var(--accent2); }
  .stat-card.completed .stat-value { color: var(--accent); }
  .stat-card.pending .stat-value { color: var(--accent4); }
  .stat-card.overdue .stat-value { color: var(--accent3); }

  /* PANEL GRID */
  .panel-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px; margin-bottom: 18px;
  }

  .card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 26px;
    box-shadow: var(--shadow-sm);
    transition: border-color 0.2s;
  }

  .card:hover { border-color: var(--border-bright); }

  .card-title {
    font-family: 'Syne', sans-serif;
    font-size: 0.95rem; font-weight: 800;
    letter-spacing: -0.01em;
    margin-bottom: 20px;
    display: flex; align-items: center; gap: 9px;
    color: var(--text);
  }

  .card-title-dot {
    width: 7px; height: 7px;
    border-radius: 50%; flex-shrink: 0;
  }

  .section-label {
    font-size: 0.68rem; font-weight: 700;
    text-transform: uppercase; letter-spacing: 0.1em;
    color: var(--muted2); margin-bottom: 14px;
  }

  /* FIELDS */
  .field { margin-bottom: 14px; }

  .field label {
    display: block; font-size: 0.69rem; font-weight: 700;
    text-transform: uppercase; letter-spacing: 0.09em;
    color: var(--muted); margin-bottom: 6px;
  }

  .field input[type="text"],
  .field input[type="date"],
  .field textarea {
    width: 100%;
    background: var(--surface2);
    border: 1.5px solid var(--border);
    border-radius: var(--radius-sm);
    color: var(--text);
    font-family: 'DM Sans', sans-serif;
    font-size: 0.88rem; font-weight: 400;
    padding: 10px 14px;
    outline: none;
    transition: border-color 0.18s, box-shadow 0.18s, background 0.18s;
  }

  .field input[type="text"]:hover,
  .field input[type="date"]:hover,
  .field textarea:hover {
    border-color: var(--border-bright);
    background: var(--surface);
  }

  .field input[type="text"]:focus,
  .field input[type="date"]:focus,
  .field textarea:focus {
    border-color: var(--accent2);
    box-shadow: 0 0 0 3px rgba(37,99,235,0.12);
    background: var(--surface);
  }

  .field input[type="text"]::placeholder,
  .field textarea::placeholder { color: var(--muted2); font-weight: 300; }

  textarea { resize: vertical; min-height: 70px; }

  /* CUSTOM SELECT */
  .custom-select-wrapper { position: relative; }

  .custom-select-btn {
    width: 100%;
    background: var(--surface2);
    border: 1.5px solid var(--border);
    border-radius: var(--radius-sm);
    color: var(--text);
    font-family: 'DM Sans', sans-serif;
    font-size: 0.88rem; font-weight: 400;
    padding: 10px 38px 10px 14px;
    text-align: left;
    cursor: pointer;
    display: flex; align-items: center;
    outline: none;
    transition: border-color 0.18s, box-shadow 0.18s, background 0.18s;
    position: relative;
  }

  .custom-select-btn:hover {
    border-color: var(--border-bright);
    background: var(--surface);
  }

  .custom-select-btn.open {
    border-color: var(--accent2);
    box-shadow: 0 0 0 3px rgba(37,99,235,0.12);
    background: var(--surface);
  }

  .custom-select-btn .placeholder { color: var(--muted2); font-weight: 300; }

  .select-arrow {
    position: absolute; right: 12px; top: 50%;
    transform: translateY(-50%);
    pointer-events: none;
    transition: transform 0.2s;
    color: var(--muted);
  }

  .custom-select-btn.open .select-arrow { transform: translateY(-50%) rotate(180deg); }

  .custom-select-dropdown {
    position: absolute; top: calc(100% + 6px); left: 0; right: 0;
    background: var(--surface);
    border: 1.5px solid var(--border-bright);
    border-radius: var(--radius-sm);
    box-shadow: var(--shadow-lg);
    z-index: 300; overflow: hidden;
    animation: dropIn 0.15s ease;
    max-height: 220px; overflow-y: auto;
  }

  @keyframes dropIn {
    from { opacity: 0; transform: translateY(-6px); }
    to { opacity: 1; transform: translateY(0); }
  }

  .select-option {
    padding: 10px 14px;
    font-size: 0.87rem; cursor: pointer;
    transition: background 0.12s;
    display: flex; align-items: center; gap: 10px;
    color: var(--text);
  }

  .select-option:hover { background: var(--surface2); }
  .select-option.selected { background: var(--accent2-dim); color: var(--accent2); font-weight: 600; }
  .select-option.placeholder-opt { color: var(--muted2); font-weight: 300; }

  .select-option-dot {
    width: 6px; height: 6px; border-radius: 50%; flex-shrink: 0;
  }

  /* STATUS SELECT */
  .status-select-wrapper { position: relative; display: inline-block; }

  .status-select-btn {
    display: inline-flex; align-items: center; gap: 7px;
    padding: 5px 28px 5px 10px;
    border-radius: 100px;
    font-family: 'DM Sans', sans-serif;
    font-size: 0.76rem; font-weight: 600;
    cursor: pointer;
    border: 1.5px solid transparent;
    transition: all 0.15s;
    outline: none;
    position: relative;
    white-space: nowrap;
  }

  .status-select-btn[data-status="pending"] {
    background: var(--accent4-dim);
    color: var(--accent4);
    border-color: rgba(234,88,12,0.2);
  }

  .status-select-btn[data-status="in-progress"] {
    background: var(--accent2-dim);
    color: var(--accent2);
    border-color: rgba(37,99,235,0.2);
  }

  .status-select-btn[data-status="completed"] {
    background: var(--accent-dim);
    color: var(--accent);
    border-color: rgba(22,163,74,0.2);
  }

  .status-select-btn:disabled {
    opacity: 0.5; cursor: not-allowed;
  }

  .status-dot {
    width: 6px; height: 6px; border-radius: 50%;
    flex-shrink: 0;
  }

  .status-select-btn[data-status="pending"] .status-dot { background: var(--accent4); }
  .status-select-btn[data-status="in-progress"] .status-dot { background: var(--accent2); }
  .status-select-btn[data-status="completed"] .status-dot { background: var(--accent); }

  .status-select-arrow {
    position: absolute; right: 8px; top: 50%;
    transform: translateY(-50%);
    pointer-events: none; color: currentColor;
    opacity: 0.7;
  }

  .status-dropdown {
    position: absolute; top: calc(100% + 5px); left: 0;
    min-width: 150px;
    background: var(--surface);
    border: 1.5px solid var(--border-bright);
    border-radius: var(--radius-xs);
    box-shadow: var(--shadow-lg);
    z-index: 400;
    animation: dropIn 0.15s ease;
    overflow: hidden;
  }

  .status-opt {
    padding: 9px 14px;
    display: flex; align-items: center; gap: 9px;
    font-size: 0.82rem; font-weight: 500;
    cursor: pointer; transition: background 0.12s;
  }

  .status-opt:hover { background: var(--surface2); }
  .status-opt-dot { width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0; }

  /* CUSTOM CHECKBOX */
  .member-list {
    border: 1.5px solid var(--border);
    border-radius: var(--radius-sm);
    background: var(--surface2);
    max-height: 168px; overflow-y: auto;
    padding: 6px;
  }

  .member-list::-webkit-scrollbar { width: 4px; }
  .member-list::-webkit-scrollbar-track { background: transparent; }
  .member-list::-webkit-scrollbar-thumb { background: var(--border-bright); border-radius: 4px; }

  .member-item {
    display: flex; align-items: center; gap: 10px;
    padding: 7px 8px; border-radius: var(--radius-xs);
    cursor: pointer;
    transition: background 0.12s;
    user-select: none;
  }

  .member-item:hover { background: var(--surface3); }
  .member-item.checked { background: var(--accent2-dim); }

  .custom-checkbox {
    width: 18px; height: 18px; border-radius: 5px;
    border: 2px solid var(--border-bright);
    background: var(--surface);
    display: flex; align-items: center; justify-content: center;
    flex-shrink: 0;
    transition: all 0.15s;
  }

  .member-item.checked .custom-checkbox {
    background: var(--accent2);
    border-color: var(--accent2);
    box-shadow: 0 0 0 3px rgba(37,99,235,0.15);
  }

  .check-icon {
    opacity: 0; transform: scale(0.5);
    transition: all 0.15s;
  }

  .member-item.checked .check-icon {
    opacity: 1; transform: scale(1);
  }

  .member-label { font-size: 0.84rem; color: var(--text); flex: 1; line-height: 1.3; }
