`;

// Custom Select Component
function CustomSelect({ value, onChange, options, placeholder = "Select...", disabled }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const handler = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);

  const selected = options.find(o => o.value === value);

  return (
    <div className="custom-select-wrapper" ref={ref}>
      <button
        type="button"
        className={`custom-select-btn${open ? " open" : ""}`}
        onClick={() => !disabled && setOpen(o => !o)}
        disabled={disabled}
      >
        {selected ? (
          <span style={{ display: "flex", alignItems: "center", gap: 8 }}>
            {selected.dot && <span className="select-option-dot" style={{ background: selected.dot }} />}
            {selected.label}
          </span>
        ) : (
          <span className="placeholder">{placeholder}</span>
        )}
        <svg className="select-arrow" width="12" height="12" viewBox="0 0 12 12" fill="none">
          <path d="M2 4l4 4 4-4" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/>
        </svg>
      </button>
      {open && (
        <div className="custom-select-dropdown">
          <div
            className={`select-option placeholder-opt${!value ? " selected" : ""}`}
            onClick={() => { onChange(""); setOpen(false); }}
          >
            {placeholder}
          </div>
          {options.map(opt => (
            <div
              key={opt.value}
              className={`select-option${opt.value === value ? " selected" : ""}`}
              onClick={() => { onChange(opt.value); setOpen(false); }}
            >
              {opt.dot && <span className="select-option-dot" style={{ background: opt.dot }} />}
              {opt.label}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// Status Select Component
const STATUS_CONFIG = {
  "pending":     { label: "Pending",     color: "#ea580c", dot: "#ea580c" },
  "in-progress": { label: "In Progress", color: "#2563eb", dot: "#2563eb" },
  "completed":   { label: "Completed",   color: "#16a34a", dot: "#16a34a" },
};

function StatusSelect({ value, onChange, disabled }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const handler = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);

  const cfg = STATUS_CONFIG[value] || STATUS_CONFIG["pending"];

  return (
    <div className="status-select-wrapper" ref={ref}>
      <button
        type="button"
        className="status-select-btn"
        data-status={value}
        onClick={() => !disabled && setOpen(o => !o)}
        disabled={disabled}
      >
        <span className="status-dot" />
        {cfg.label}
        <svg className="status-select-arrow" width="10" height="10" viewBox="0 0 10 10" fill="none">
          <path d="M2 3.5l3 3 3-3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
        </svg>
      </button>
      {open && (
        <div className="status-dropdown">
          {Object.entries(STATUS_CONFIG).map(([key, cfg]) => (
            <div
              key={key}
              className="status-opt"
              onClick={() => { onChange(key); setOpen(false); }}
            >
              <span className="status-opt-dot" style={{ background: cfg.dot }} />
              <span style={{ color: key === value ? cfg.color : "inherit", fontWeight: key === value ? 700 : 500 }}>
                {cfg.label}
              </span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// Custom Checkbox Member Item
function MemberCheckItem({ member, checked, onChange }) {
