              </svg>
              {error}
            </div>
          )}

          {/* STATS */}
          <div className="stats">
            {[
              {
                label: "Total Tasks", value: stats.total, cls: "total",
                icon: <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><rect x="1" y="1" width="14" height="14" rx="3" stroke="#2563eb" strokeWidth="1.4"/><path d="M4 8h8M4 5h8M4 11h5" stroke="#2563eb" strokeWidth="1.4" strokeLinecap="round"/></svg>
              },
              {
                label: "Completed", value: stats.completed, cls: "completed",
                icon: <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><circle cx="8" cy="8" r="6.5" stroke="#16a34a" strokeWidth="1.4"/><path d="M5 8l2.5 2.5L11 5.5" stroke="#16a34a" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
              },
              {
