                icon: <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><circle cx="8" cy="8" r="6.5" stroke="#ea580c" strokeWidth="1.4"/><path d="M8 4.5V8l2.5 2" stroke="#ea580c" strokeWidth="1.5" strokeLinecap="round"/></svg>
